def clean(df):
    df = df.copy()
    # Fix Category label variants (extra spaces)
    if 'Category' in df.columns:
        df['Category'] = df['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # Remove exact duplicate rows (Order_ID duplicates are exact duplicates)
    df = df.drop_duplicates()
    return df

def answer(df):
    # Count orders per Category, drop missing group keys
    if 'Category' not in df.columns:
        return {}
    d = df.dropna(subset=['Category'])
    # strip again in case answer called without clean
    d = d.copy()
    d['Category'] = d['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    counts = d.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
